async function main(): Promise<void> {
  const arr: number[] = [1, 2];
  const a: any = arr;
  a.push(3);
  console.log(arr.length, arr.join(","));
  arr.push(4);
  console.log(a.length, a[3]);
  a[0] = 9;
  console.log(arr[0]);
  console.log(a.map((x: number) => x * 2).join(","));
  console.log(Array.isArray(a), JSON.stringify(a));
}
